// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Vault {
    uint256 public total;

    error TooSmall(uint256 minimum);

    function deposit(uint256 amount) external {
        if (amount < 10) {
            revert TooSmall(10);
        }

        total += amount;
    }
}

